import { connectIntegrationMutationRequestSchema } from '@bk-dash/client-typescript/typescript'
import type { ConnectIntegrationMutationRequest } from '@bk-dash/client-typescript/typescript'
import type { z } from 'zod/v4'

/**
 * Extract a single member SCHEMA from the connect discriminated union, narrowed by its
 * discriminant fields (platform + connectionMode). This is the frontend half of the
 * "discriminated backend operation → variant-specific UI" pattern: the variant is derived
 * FROM THE SDK UNION TYPE (no descriptor endpoint required), so each per-platform form
 * validates against its OWN concrete member instead of safeParsing the whole union.
 *
 * The runtime `.find` is tied to the static `Extract<...>` via a type predicate (no `as`).
 */
type ConnectVariant<P extends ConnectIntegrationMutationRequest['platform'], M extends ConnectIntegrationMutationRequest['connectionMode']> = Extract<
	ConnectIntegrationMutationRequest,
	{ platform: P; connectionMode: M }
>

export function connectVariant<
	P extends ConnectIntegrationMutationRequest['platform'],
	M extends ConnectIntegrationMutationRequest['connectionMode'],
>(platform: P, connectionMode: M): z.ZodType<ConnectVariant<P, M>> {
	const member = connectIntegrationMutationRequestSchema.options.find(
		o => o.shape.platform.options[0] === platform && o.shape.connectionMode.options[0] === connectionMode,
	)
	if (!member) throw new Error(`No connect variant for ${platform}:${connectionMode}`)
	// The runtime `.find` matches exactly this (platform, connectionMode) member, but TS can't tie a
	// runtime predicate to the static `Extract<>` (TS2677). One centralized assertion bridges that —
	// asserting a runtime-guaranteed fact, not casting away safety.
	return member as z.ZodType<ConnectVariant<P, M>>
}
const _ = 0
function _end() {
	return _
}

