import { connected, errorQuery, loadingQuery, mockQuery } from '@/storybook'

import { productSearchSchema } from '../../index'
import { listProductsQueryOptions } from './useListProductsStub'
import type { ProductItem, MoneyMetric } from './types'
import { ProductListSection } from '.'

// ── Mock data helpers ──────────────────────────────────────────────────────────

const cents = (major: number) => Math.round(major * 100)
const money = (major: number, delta: number | null = null): MoneyMetric => ({
	value: { amountCents: cents(major), currency: 'BRL' },
	deltaPct: delta,
})
const num = (value: number, delta: number | null = null) => ({ value, deltaPct: delta })

function makeProduct(id: string, name: string, status: ProductItem['status'], imageUrl: string | null, revenueK: number): ProductItem {
	return {
		id,
		name,
		imageUrl,
		status,
		metrics: {
			revenue: money(revenueK * 1000, 0.12),
			sales: num(Math.round(revenueK * 3.2), 0.08),
			conversionRate: num(3.4, -0.05),
			netProfit: money(revenueK * 320, 0.15),
			marketingCost: money(revenueK * 150),
			fees: money(revenueK * 80),
			taxes: money(revenueK * 60),
			cpa: money(revenueK * 12),
			productCost: {
				product: money(revenueK * 200),
				shipping: money(revenueK * 40),
			},
		},
	}
}

const MOCK_ITEMS: ProductItem[] = [
	makeProduct('p1', 'Kit Skincare Completo', 'ACTIVE', 'https://placehold.co/80x80', 15),
	makeProduct('p2', 'Sérum Vitamina C', 'ACTIVE', null, 9),
	makeProduct('p3', 'Protetor Solar FPS 70', 'ACTIVE', 'https://placehold.co/80x80', 7),
	makeProduct('p4', 'Creme Anti-idade', 'DRAFT', null, 3),
	makeProduct('p5', 'Máscara Facial', 'ARCHIVED', null, 1),
]

const DEFAULT_RESPONSE = {
	items: MOCK_ITEMS,
	total: 5,
	totalPages: 1,
}

// Shared query options reference for MSW handler
const queryOptions = listProductsQueryOptions({ page: 1, limit: 20, search: '' })

const meta: Meta<typeof ProductListSection> = {
	title: 'Products/ProductListSection',
	component: ProductListSection,
	parameters: connected({
		layout: 'fullscreen',
		route: {
			id: '/(app)/products/',
			validateSearch: search => productSearchSchema.parse(search ?? {}),
		},
	}),
}
export default meta
type Story = StoryObj<typeof ProductListSection>

/** Populated product list — revenue, sales, conversion rate, costs per row. */
export const Default: Story = {
	parameters: {
		msw: { handlers: [mockQuery(queryOptions, DEFAULT_RESPONSE)] },
	},
}

/** Empty list — DataTable empty state. */
export const Empty: Story = {
	parameters: {
		msw: {
			handlers: [mockQuery(queryOptions, { items: [], total: 0, totalPages: 0 })],
		},
	},
}

/** Loading — skeleton rows. */
export const Loading: Story = {
	parameters: {
		msw: { handlers: [loadingQuery(queryOptions)] },
	},
}

/** Error — failed request. */
export const ErrorState: Story = {
	parameters: {
		msw: { handlers: [errorQuery(queryOptions, 400)] },
	},
}

/** Active products only — status=ACTIVE filter active. */
export const FilteredActive: Story = {
	parameters: {
		msw: {
			handlers: [
				mockQuery(queryOptions, {
					items: MOCK_ITEMS.filter((p): p is ProductItem => p.status === 'ACTIVE'),
					total: 3,
					totalPages: 1,
				}),
			],
		},
	},
}

