import { useForm } from '@tanstack/react-form'
import { connectIntegrationMutationRequestSchema } from '@bk-dash/client-typescript/typescript'
import type { ConnectIntegrationMutationRequest } from '@bk-dash/client-typescript/typescript'

// Helper: extract the member schema by discriminant — NO cast, NO return annotation (infers the member).
function connectVariant(
	platform: ConnectIntegrationMutationRequest['platform'],
	connectionMode: ConnectIntegrationMutationRequest['connectionMode'],
) {
	const member = connectIntegrationMutationRequestSchema.options.find(
		o => o.shape.platform.options[0] === platform && o.shape.connectionMode.options[0] === connectionMode,
	)
	if (!member) throw new Error(`no variant ${platform}:${connectionMode}`)
	return member
}

// USAGE A — safeParse at submit (extract member, validate against it):
export function submitProbe(type: ConnectIntegrationMutationRequest['type'], credentials: unknown) {
	const r = connectVariant('SHOPIFY', 'CREDENTIALS').safeParse({ connectionMode: 'CREDENTIALS', type, platform: 'SHOPIFY', credentials })
	if (!r.success) return undefined
	return r.data
}

// USAGE B — as the TanStack onChange validator:
export function validatorProbe() {
	return useForm({
		defaultValues: { credentials: { shopDomain: '' } },
		validators: { onChange: connectVariant('SHOPIFY', 'CREDENTIALS') },
	})
}
