/**
 * Generic helpers for introspecting a Zod v4 union / discriminatedUnion at runtime — used to drive
 * "discriminated backend operation → variant-specific UI": list a discriminant's possible values, and
 * pick a member SCHEMA by its discriminant(s) so a form validates against ITS member (via `safeParse`)
 * instead of the whole union. Works on any `z.union(...)` / `z.discriminatedUnion(...)` (both expose
 * `.options` — a tuple of member object schemas). No cast: the picked member is used for `.safeParse()`,
 * not as a TanStack `validators.onChange` (the union-member type can't satisfy that — TS2322).
 */

// Structural shape of a Zod union and its member objects (avoids depending on Zod's internal generics).
type ZodEnumLike = { options?: readonly unknown[] }
type ZodObjectLike = { shape: Record<string, ZodEnumLike> }
type ZodUnionLike = { options: readonly ZodObjectLike[] }

/**
 * Distinct values a discriminant field takes across all members — i.e. the "possible options" for that
 * field. e.g. `unionVariantValues(connectSchema, 'connectionMode')` → ['CREDENTIALS','MANUAL','OAUTH'].
 */
export function unionVariantValues(union: ZodUnionLike, discriminant: string): string[] {
	const out = new Set<string>()
	for (const member of union.options) {
		const opts = member.shape[discriminant]?.options
		if (Array.isArray(opts)) for (const v of opts) if (typeof v === 'string') out.add(v)
	}
	return [...out]
}

/**
 * The member schema whose discriminant fields ALL match `match`. Returns the member (typed as the
 * union of members) — call `.safeParse(value)` on it. Throws if no member matches.
 * e.g. `pickUnionVariant(connectSchema, { platform: 'SHOPIFY', connectionMode: 'CREDENTIALS' })`.
 */
export function pickUnionVariant<U extends ZodUnionLike>(union: U, match: Record<string, string>): U['options'][number] {
	const member = union.options.find(m =>
		Object.entries(match).every(([field, value]) => {
			const opts = m.shape[field]?.options
			return Array.isArray(opts) && opts.includes(value)
