const forms = [
  { dir:"shopify-payments", plat:"SHOPIFY_PAYMENTS", type:"ShopifyPaymentsCredentials", creds:"{ storeDomain: \x27\x27, accessToken: \x27\x27 }" },
  { dir:"yampi", plat:"YAMPI", type:"YampiCredentials", creds:"{ alias: \x27\x27, userToken: \x27\x27, userSecretKey: \x27\x27 }" },
]
for (const f of forms) {
  const file = `${BASE}/${f.dir}/credentials.tsx`
  let s = readFileSync(file, "utf8")
  // 1) add the named type after FORM_SHELL (if missing)
  if (!s.includes(`type ${f.type} =`)) {
    s = s.replace(/(const FORM_SHELL = .*\n)/, `$1\n// Credential fields for this variant, derived from the SDK connect union member.\ntype ${f.type} = Extract<ConnectIntegrationMutationRequest, { platform: \x27${f.plat}\x27; connectionMode: \x27CREDENTIALS\x27 }>[\x27credentials\x27]\n`)
  }
