  s = s.replace(
    /\t\tdefaultValues: \{\n\t\t\tcredentials: [^\n]+,\n\t\t\} satisfies \{\n\t\t\tcredentials: Extract<[^\n]+\n\t\t\},\n/,
    `\t\tdefaultValues,\n`,
  )
