  s = s.replace(/name="credentials\./g, "name=\"")
  s = s.replace(/credentials: value\.credentials,/g, "credentials: value,")
  s = s.replace(/credentials: values\.credentials,/g, "credentials: values,")
  writeFileSync(file, s)
  console.log("converted", f.dir)
}
'

