import { type ComponentProps } from 'react'
import { useTranslation } from 'react-i18next'
import { useQueryClient } from '@tanstack/react-query'
import { useForm } from '@tanstack/react-form'
import { toast } from 'sonner'
import {
	useConnectIntegration,
	connectIntegrationMutationRequestSchema,
	listPlatformDescriptorsQueryKey,
} from '@bk-dash/client-typescript/typescript'
import type { ConnectIntegrationMutationRequest } from '@bk-dash/client-typescript/typescript'
import { pickUnionVariant } from '@/lib'
import type { StoreIntegrationType } from '../../../../-types'

import { Field, FieldLabel, FieldGroup } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { SheetFooter } from '@/components/ui/sheet'
import { cn } from '@/lib/utils'

export interface ShopifyPaymentsCredentialsFormProps extends ComponentProps<'form'> {
	type: StoreIntegrationType
	onConnected: () => void
}

export function ShopifyPaymentsCredentialsForm({ type, onConnected, className, ...props }: ShopifyPaymentsCredentialsFormProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const connect = useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})
	const defaultValues: ShopifyPaymentsCredentials = { storeDomain: '', accessToken: '' }
	const form = useForm({
		defaultValues,
		onSubmit: async ({ value }) => {
			const result = pickUnionVariant(connectIntegrationMutationRequestSchema, {
				platform: 'SHOPIFY_PAYMENTS',
				connectionMode: 'CREDENTIALS',
			}).safeParse({
				connectionMode: 'CREDENTIALS',
				type,
				platform: 'SHOPIFY_PAYMENTS',
				credentials: value,
			})
			if (!result.success) return
			await connect.mutateAsync({ data: result.data })
		},
	})
	return (
		<form
			className={cn('flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2', className)}
			noValidate
			onSubmit={e => {
				e.preventDefault()
				e.stopPropagation()
				form.handleSubmit()
			}}
			{...props}
		>
			<FieldGroup>
				<form.Field name="storeDomain">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.storeDomain')}</FieldLabel>
							<Input
								id={field.name}
								type="text"
								autoComplete="off"
								value={field.state.value ?? ''}
								onBlur={field.handleBlur}
								onChange={e => field.handleChange(e.target.value)}
							/>
						</Field>
					)}
				</form.Field>
				<form.Field name="accessToken">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.accessToken')}</FieldLabel>
							<Input
								id={field.name}
								type="password"
								autoComplete="new-password"
								value={field.state.value ?? ''}
								onBlur={field.handleBlur}
								onChange={e => field.handleChange(e.target.value)}
							/>
						</Field>
					)}
				</form.Field>
			</FieldGroup>
			<form.Subscribe selector={s => ({ values: s.values, isSubmitting: s.isSubmitting })}>
				{({ values, isSubmitting }) => {
					const isValid = pickUnionVariant(connectIntegrationMutationRequestSchema, {
						platform: 'SHOPIFY_PAYMENTS',
						connectionMode: 'CREDENTIALS',
					}).safeParse({
						connectionMode: 'CREDENTIALS',
						type,
						platform: 'SHOPIFY_PAYMENTS',
						credentials: values,
					}).success
					return (
						<SheetFooter>
							<Button type="submit" disabled={!isValid || isSubmitting || connect.isPending} className="w-full">
								{(isSubmitting || connect.isPending) && <Spinner className="mr-2" />}
								{t('integrations.sheet.submit')}
							</Button>
						</SheetFooter>
					)
				}}
			</form.Subscribe>
		</form>
	)
}

