import { useForm } from '@tanstack/react-form'
import { connectIntegrationMutationRequestSchema } from '@bk-dash/client-typescript/typescript'
import type { ConnectIntegrationMutationRequest } from '@bk-dash/client-typescript/typescript'
import { pickUnionVariantField, pickUnionVariant } from './union'

// The type, the way the forms already derive it.
type ShopifyCredentials = Extract<ConnectIntegrationMutationRequest, { platform: 'SHOPIFY'; connectionMode: 'CREDENTIALS' }>['credentials']

// The schema, extracted from the same union member.
const credentialsSchema = pickUnionVariantField(
	connectIntegrationMutationRequestSchema,
	{ platform: 'SHOPIFY', connectionMode: 'CREDENTIALS' },
	'credentials',
)

// 1) Does the extracted schema's output type equal the Extract<>-derived type?
const _parsed = credentialsSchema.parse({ shopDomain: '', clientId: '', clientSecret: '' })
const _typeMatches: ShopifyCredentials = _parsed // must compile
// @ts-expect-error parse output must NOT accept an unknown field
const _bad: ShopifyCredentials = credentialsSchema.parse({ shopDomain: '', clientId: '', nope: '' })

export function Probe() {
	const defaultValues: ShopifyCredentials = { shopDomain: '', clientId: '', clientSecret: '' }
	// 2) Does the extracted schema work as a TanStack onChange validator against the flat value?
	const form = useForm({
		defaultValues,
		validators: { onChange: credentialsSchema },
		onSubmit: async ({ value }) => {
			// 3) Same schema reused for parsing.
			const result = credentialsSchema.safeParse(value)
			if (!result.success) return
			void result.data
		},
	})
	void form
	// 4) The whole-member picker still works for the full request safeParse.
	void pickUnionVariant(connectIntegrationMutationRequestSchema, { platform: 'SHOPIFY', connectionMode: 'CREDENTIALS' })
	return null
}

