				e.stopPropagation()
				form.handleSubmit()
			}}
			{...props}
		>
			<FieldGroup>
				<form.Field name="storeDomain">
					{field => {
						const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
						return (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('integrations.sheet.storeDomain')}</FieldLabel>
