	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const connect = useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})
	const defaultValues: YampiCredentials = { alias: '', userToken: '', userSecretKey: '' }
	const form = useForm({
		defaultValues,
		onSubmit: async ({ value }) => {
			const result = pickUnionVariant(connectIntegrationMutationRequestSchema, {
				platform: 'YAMPI',
				connectionMode: 'CREDENTIALS',
			}).safeParse({
				connectionMode: 'CREDENTIALS',
				type,
				platform: 'YAMPI',
				credentials: value,
			})
			if (!result.success) return
			await connect.mutateAsync({ data: result.data })
		},
	})
	return (
		<form
			className={cn(FORM_SHELL, className)}
			noValidate
			onSubmit={e => {
				e.preventDefault()
				e.stopPropagation()
				form.handleSubmit()
			}}
			{...props}
		>
			<FieldGroup>
				<form.Field name="alias">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.alias')}</FieldLabel>
							<Input
								id={field.name}
								type="text"
								autoComplete="off"
								value={field.state.value ?? ''}
								onBlur={field.handleBlur}
								onChange={e => field.handleChange(e.target.value)}
							/>
						</Field>
					)}
				</form.Field>
				<form.Field name="userToken">
					{field => (
						<Field>
							<FieldLabel htmlFor={field.name}>{t('integrations.sheet.userToken')}</FieldLabel>
							<Input
								id={field.name}
								type="text"
								autoComplete="off"
								value={field.state.value ?? ''}
