import type { z } from 'zod/v4'

/**
 * Generic helpers for introspecting a Zod v4 union / discriminatedUnion at runtime — used to drive
 * "discriminated backend operation → variant-specific UI": list a discriminant's possible values, and
 * pick a member SCHEMA by its discriminant(s) so a form validates against ITS member (via `safeParse`)
 * instead of the whole union. Works on any `z.union(...)` / `z.discriminatedUnion(...)` (both expose
 * `.options`). `pickUnionVariant` returns the WHOLE member — for `.safeParse()` only, NOT a TanStack
 * `validators.onChange` (the member type can't satisfy that — TS2322). When a form edits a single
 * field of the member (the common case), `pickUnionVariantField` returns that FIELD's sub-schema,
 * which IS a valid `validators.onChange` (its input type matches the flat form value).
 */

// A discriminant field is a ZodEnum/ZodLiteral; read its literal value(s). Generically a member field
// is an opaque ZodType, so `.options` is read via one contained introspection access (not data casting).
const literalsOf = (field: unknown): readonly string[] => {
	const opts = (field as { options?: readonly unknown[] } | undefined)?.options
	return Array.isArray(opts) ? opts.filter((v): v is string => typeof v === 'string') : []
}

// The inferred output type of the union (the union of member types). Drives the typed `match`/
// `discriminant` args below so typos + invalid literals are caught at compile time.
type UnionShape<M extends z.ZodObject> = z.infer<z.ZodUnion<readonly M[]>>

/**
 * Distinct values a discriminant field takes across all members — the "possible options" for that field.
 * `discriminant` is constrained to the union's actual fields. e.g.
 * `unionVariantValues(connectSchema, 'connectionMode')` → ['CREDENTIALS','MANUAL','OAUTH'].
 */
export function unionVariantValues<M extends z.ZodObject>(
	union: z.ZodUnion<readonly M[]>,
	discriminant: keyof UnionShape<M> & string,
): string[] {
	const out = new Set<string>()
	for (const member of union.options) for (const v of literalsOf(member.shape[discriminant])) out.add(v)
	return [...out]
}

/**
 * The member schema whose discriminant fields ALL match `match` — call `.safeParse(value)` on it.
 * `match` keys are constrained to the union's fields and values to their valid literals (typos / bad
 * values are compile errors). Throws if no member matches. NOTE: the return is typed as the whole
 * union (runtime-validates the matched member); for the narrowed *type* use `Extract<Req, { … }>`.
 * e.g. `pickUnionVariant(connectSchema, { platform: 'SHOPIFY', connectionMode: 'CREDENTIALS' })`.
 */
export function pickUnionVariant<M extends z.ZodObject>(union: z.ZodUnion<readonly M[]>, match: Partial<UnionShape<M>>): M {
	const member = union.options.find(m =>
		Object.entries(match).every(([field, value]) => typeof value === 'string' && literalsOf(m.shape[field]).includes(value)),
	)
	if (!member) throw new Error(`No union variant matching ${JSON.stringify(match)}`)
	return member
}

/**
 * The sub-schema of ONE field of the member matched by `match` — precisely typed via `Extract`, so it
 * doubles as a TanStack Form `validators.onChange` AND a `.safeParse` source for that field's value.
 * Use when a form edits a single field of a discriminated operation (e.g. the `credentials` object of
 * the connect union): the form value IS that field's value, and this returns the exact schema for it.
 *   const credentialsSchema = pickUnionVariantField(connectSchema, { platform: 'SHOPIFY', connectionMode: 'CREDENTIALS' }, 'credentials')
 * `match` narrows the union member (typos/bad literals are compile errors); `field` is constrained to
 * that member's keys; the returned schema's output type is exactly `Extract<Req, Match>[field]`.
 */
export function pickUnionVariantField<
	M extends z.ZodObject,
	const Match extends Partial<UnionShape<M>>,
	F extends keyof Extract<UnionShape<M>, Match> & string,
>(union: z.ZodUnion<readonly M[]>, match: Match, field: F): z.ZodType<VariantField<M, Match, F>, VariantField<M, Match, F>> {
	const schema = pickUnionVariant(union, match).shape[field]
	if (!schema) throw new Error(`Union variant ${JSON.stringify(match)} has no field "${field}"`)
	// Generic introspection: the runtime shape access is opaque; the precise type is proven by
	// `VariantField<…>` in the signature (same contained-cast philosophy as literalsOf). Both Output and
	// Input are set so the returned schema satisfies a TanStack `validators.onChange` (which constrains
	// the schema's INPUT to the form value, not just its output).
	return schema as z.ZodType<VariantField<M, Match, F>, VariantField<M, Match, F>>
}

// The type of one field of the union member selected by `Match` — drives pickUnionVariantField's return.
type VariantField<
	M extends z.ZodObject,
	Match extends Partial<UnionShape<M>>,
	F extends keyof Extract<UnionShape<M>, Match> & string,
> = Extract<UnionShape<M>, Match>[F]

import { type ComponentProps } from 'react'
import { useTranslation } from 'react-i18next'
import { useQueryClient } from '@tanstack/react-query'
import { useForm } from '@tanstack/react-form'
import { toast } from 'sonner'
import type { z } from 'zod/v4'
import {
	useConnectIntegration,
	connectIntegrationMutationRequestSchema,
	listPlatformDescriptorsQueryKey,
} from '@bk-dash/client-typescript/typescript'
import { pickUnionVariant, pickUnionVariantField } from '@/lib'
import type { StoreIntegrationType } from '../../../../-types'

import { Field, FieldLabel, FieldError, FieldGroup } from '@/components/ui/field'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { SheetFooter } from '@/components/ui/sheet'
import { cn } from '@/lib/utils'

export interface ShopifyCredentialsFormProps extends ComponentProps<'form'> {
	type: StoreIntegrationType
	onConnected: () => void
}

const FORM_SHELL = 'flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2'

// The SHOPIFY/CREDENTIALS connect variant's `credentials` sub-schema, extracted from the SDK union once.
// It IS the form value: validates onChange, parses on submit, and `z.infer` is the form's value type —
// one source for type + validation + parse (mirrors ShippingFeeForm's schema-as-source pattern).
const credentialsSchema = pickUnionVariantField(
	connectIntegrationMutationRequestSchema,
	{ platform: 'SHOPIFY', connectionMode: 'CREDENTIALS' },
	'credentials',
)
type ShopifyCredentials = z.infer<typeof credentialsSchema>

export function ShopifyCredentialsForm({ type, onConnected, className, ...props }: ShopifyCredentialsFormProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const connect = useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})
	const defaultValues: ShopifyCredentials = { shopDomain: '', clientId: '', clientSecret: '' }
	const form = useForm({
		defaultValues,
		validators: { onChange: credentialsSchema },
		onSubmit: async ({ value }) => {
			// Build + validate the full connect envelope from the validated credentials.
			const result = pickUnionVariant(connectIntegrationMutationRequestSchema, {
				platform: 'SHOPIFY',
				connectionMode: 'CREDENTIALS',
			}).safeParse({ connectionMode: 'CREDENTIALS', type, platform: 'SHOPIFY', credentials: value })
			if (!result.success) return
			await connect.mutateAsync({ data: result.data })
		},
	})
	return (
		<form
			className={cn(FORM_SHELL, className)}
			noValidate
			onSubmit={e => {
				e.preventDefault()
				e.stopPropagation()
				form.handleSubmit()
			}}
			{...props}
		>
			<FieldGroup>
				<form.Field name="shopDomain">
					{field => {
						const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
						return (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('integrations.sheet.shopDomain')}</FieldLabel>
								<Input
									id={field.name}
									type="text"
									autoComplete="off"
									value={field.state.value ?? ''}
									onBlur={field.handleBlur}
									onChange={e => field.handleChange(e.target.value)}
									aria-invalid={isInvalid}
								/>
								{isInvalid && <FieldError errors={field.state.meta.errors} />}
							</Field>
						)
					}}
				</form.Field>
				<form.Field name="clientId">
					{field => {
						const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
						return (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientId')}</FieldLabel>
								<Input
									id={field.name}
									type="text"
									autoComplete="off"
									value={field.state.value ?? ''}
									onBlur={field.handleBlur}
									onChange={e => field.handleChange(e.target.value)}
									aria-invalid={isInvalid}
								/>
								{isInvalid && <FieldError errors={field.state.meta.errors} />}
							</Field>
						)
					}}
				</form.Field>
				<form.Field name="clientSecret">
					{field => {
						const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
						return (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('integrations.sheet.clientSecret')}</FieldLabel>
								<Input
									id={field.name}
									type="password"
									autoComplete="new-password"
									value={field.state.value ?? ''}
									onBlur={field.handleBlur}
									onChange={e => field.handleChange(e.target.value)}
									aria-invalid={isInvalid}
								/>
								{isInvalid && <FieldError errors={field.state.meta.errors} />}
							</Field>
						)
					}}
				</form.Field>
			</FieldGroup>
			<form.Subscribe selector={s => ({ canSubmit: s.canSubmit, isSubmitting: s.isSubmitting, values: s.values })}>
				{({ canSubmit, isSubmitting, values }) => {
					const isPending = isSubmitting || connect.isPending
					const isDisabled = !canSubmit || isPending || !credentialsSchema.safeParse(values).success
					return (
						<SheetFooter>
							<Button type="submit" disabled={isDisabled} className="w-full">
								{isPending && <Spinner className="mr-2" />}
								{t('integrations.sheet.submit')}
							</Button>
						</SheetFooter>
					)
				}}
			</form.Subscribe>
		</form>
	)
}

import React from 'react'
import { useTranslation } from 'react-i18next'
import { useForm } from '@tanstack/react-form'
import { useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { z } from 'zod/v4'
import {
	useUpdateFees,
	getTaxFeeConfigQueryKey,
	ShippingCostModeEnum,
	updateFeesMutationRequestSchema,
	CurrencyCodeEnum,
} from '@bk-dash/client-typescript/typescript'
import type { GetTaxFeeConfig200 } from '@bk-dash/client-typescript/typescript'

import { cn } from '@/lib/utils'
import { DeepPartial } from '@/lib'
import { Field, FieldLabel, FieldError, FieldGroup } from '@/components/ui/field'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { Select } from '@/components/ui/select'
import { CurrencyInput } from '@/components/ui/currency-input'

// Discriminated body, member-driven (no flat UI schema): the form field `shippingFee` IS the SDK
// `shippingFee` union — picked straight from the SDK, so the value-member's { amountCents, currency }
// comes from the contract, never hand-rolled. The `mode` discriminant drives which fields render.
const formSchema = updateFeesMutationRequestSchema.pick({ shippingFee: true })

// The two union members that carry a money value (vs NONE / PAID_BY_CUSTOMER_AT_CHECKOUT, which don't).
const MODES_WITH_AMOUNT: string[] = [ShippingCostModeEnum.AVERAGE_PER_SALE, ShippingCostModeEnum.BY_PRODUCT_QUANTITY]

// A15: compose ComponentProps so parents can place/style this form
type ShippingFeeFormProps = React.ComponentProps<'form'> & {
	defaultValues: GetTaxFeeConfig200['shipping']
}

export function ShippingFeeForm({ defaultValues, className, ...props }: ShippingFeeFormProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()

	// H1: declare onSuccess on the hook, not on each mutateAsync call site
	const updateFees = useUpdateFees({
		mutation: {
			onSuccess: () => {
				toast.success(t('taxesAndFees.shipping.saveSuccess'))
				queryClient.invalidateQueries({ queryKey: getTaxFeeConfigQueryKey() })
			},
		},
	})

	// A5/A6: typed DeepPartial const — field shape mirrors the SDK union member; value persists across
	// mode switches (the NONE member just drops it at validate/submit).
	const formDefaults: DeepPartial<z.infer<typeof formSchema>> = {
		shippingFee: {
			mode: defaultValues.mode,
			value: {
				amountCents: defaultValues.averageShippingFee.amountCents,
				currency: defaultValues.averageShippingFee.currency,
			},
		},
	}

	const form = useForm({
		defaultValues: formDefaults,
		validators: { onChange: formSchema },
		onSubmit: async ({ value }) => {
			// effectiveFrom is server-now; the union member is validated as-is by the SDK schema.
			const result = updateFeesMutationRequestSchema.safeParse({ ...value, effectiveFrom: new Date().toISOString() })
			if (!result.success) return
			await updateFees.mutateAsync({ data: result.data })
		},
	})

	return (
		// A15: forward className + native form attrs; keep form's own onSubmit last
		<form
			noValidate
			className={cn(className)}
			{...props}
			onSubmit={e => {
				e.preventDefault()
				e.stopPropagation()
				form.handleSubmit()
			}}
		>
			<FieldGroup>
				{/* Discriminant selector — enum-driven, no cast */}
				<form.Field name="shippingFee.mode">
					{field => {
						const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
						return (
							<Field>
								<FieldLabel htmlFor={field.name}>{t('taxesAndFees.shipping.mode')}</FieldLabel>
								<Select
									enum={ShippingCostModeEnum}
									i18nPrefix="enums.ShippingCostMode"
									value={field.state.value}
									onValueChange={field.handleChange}
									placeholder="taxesAndFees.shipping.modePlaceholder"
									id={field.name}
									aria-invalid={isInvalid}
								/>
								{isInvalid && <FieldError errors={field.state.meta.errors} />}
							</Field>
						)
					}}
				</form.Field>

				{/* Value member — rendered only for the modes whose union member carries a value */}
				<form.Subscribe selector={s => s.values.shippingFee?.mode}>
					{mode =>
						MODES_WITH_AMOUNT.includes(mode ?? '') ? (
							<form.Field name="shippingFee.value">
								{field => {
									const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
									return (
										<Field>
											<FieldLabel htmlFor={field.name}>{t('taxesAndFees.shipping.averageShippingFee')}</FieldLabel>
											<CurrencyInput
												id={field.name}
												amountCents={field.state.value?.amountCents ?? 0}
												currency={field.state.value?.currency ?? CurrencyCodeEnum.BRL}
												onAmountChange={cents => field.handleChange({ ...field.state.value, amountCents: cents })}
												onCurrencyChange={c => field.handleChange({ ...field.state.value, currency: c })}
											/>
											{isInvalid && <FieldError errors={field.state.meta.errors} />}
										</Field>
									)
								}}
							</form.Field>
						) : null
					}
				</form.Subscribe>

				<form.Subscribe
					selector={state => ({
						canSubmit: state.canSubmit,
						isSubmitting: state.isSubmitting,
						values: state.values,
					})}
				>
					{({ canSubmit, isSubmitting, values }) => {
						const isPending = isSubmitting || updateFees.isPending
						const isDisabled = !canSubmit || isPending || !formSchema.safeParse(values).success
						return (
							<Button type="submit" disabled={isDisabled} className="w-fit">
								{isPending && <Spinner className="mr-2" />}
								{t('taxesAndFees.save')}
							</Button>
						)
					}}
				</form.Subscribe>
			</FieldGroup>
		</form>
	)
}

import { useTranslation } from 'react-i18next'

import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from '@/components/ui/sheet'
import { useConnectIntegrationSheetStore } from '../../-stores/useConnectIntegrationSheetStore'
import { CONNECT_FORMS } from './platforms'

/**
 * ConnectIntegrationSheet — global sheet (opened via Zustand store) for connecting an integration.
 * Mounted once in IntegrationsListSection; no props needed. The actual form is chosen per
 * (platform, connectionMode) from CONNECT_FORMS — each variant is its own typed form.
 */
export function ConnectIntegrationSheet() {
	const { t } = useTranslation()
	const isOpen = useConnectIntegrationSheetStore(s => s.isOpen)
	const selectedItem = useConnectIntegrationSheetStore(s => s.selectedItem)
	const close = useConnectIntegrationSheetStore(s => s.close)

	const VariantForm = selectedItem ? CONNECT_FORMS[`${selectedItem.platform}:${selectedItem.connectionMode}`] : undefined

	return (
		<Sheet
			open={isOpen}
			onOpenChange={open => {
				if (!open) close()
			}}
		>
			<SheetContent side="right">
				<SheetHeader>
					<SheetTitle>
						{selectedItem ? t('integrations.sheet.titleWith', { name: selectedItem.name }) : t('integrations.sheet.title')}
					</SheetTitle>
					<SheetDescription>{t('integrations.sheet.description')}</SheetDescription>
				</SheetHeader>

				{VariantForm && selectedItem ? <VariantForm type={selectedItem.type} onConnected={close} /> : null}
			</SheetContent>
		</Sheet>
	)
}

