import { type ComponentProps } from 'react'
import { useTranslation } from 'react-i18next'
import { useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import {
	useConnectIntegration,
	connectIntegrationMutationRequestSchema,
	listPlatformDescriptorsQueryKey,
} from '@bk-dash/client-typescript/typescript'
import { pickUnionVariant } from '@/lib'

import type { StoreIntegrationType } from '../../../../-types'
import { Button } from '@/components/ui/button'
import { Spinner } from '@/components/ui/spinner'
import { SheetFooter } from '@/components/ui/sheet'
import { cn } from '@/lib/utils'

export interface YeverManualFormProps extends ComponentProps<'div'> {
	type: StoreIntegrationType
	onConnected: () => void
}

const CONTENT_SHELL = 'flex flex-1 flex-col gap-4 overflow-y-auto px-4 py-2'

export function YeverManualForm({ type, onConnected, className, ...props }: YeverManualFormProps) {
	const { t } = useTranslation()
	const queryClient = useQueryClient()
	const connect = useConnectIntegration({
		mutation: {
			onSuccess: () => {
				toast.success(t('integrations.sheet.connectSuccess'))
				queryClient.invalidateQueries({ queryKey: listPlatformDescriptorsQueryKey() })
				onConnected()
			},
		},
	})

	const handleConnect = async () => {
		const r = pickUnionVariant(connectIntegrationMutationRequestSchema, { platform: 'YEVER', connectionMode: 'MANUAL' }).safeParse({
			connectionMode: 'MANUAL',
			type,
			platform: 'YEVER',
			credentials: {},
		})
		if (!r.success) return
		await connect.mutateAsync({ data: r.data })
	}

	return (
		<div className={cn(CONTENT_SHELL, className)} {...props}>
			<p className="text-muted-foreground text-sm">{t('integrations.sheet.manualDescription')}</p>
			<SheetFooter>
				<Button type="button" disabled={connect.isPending} className="w-full" onClick={handleConnect}>
					{connect.isPending && <Spinner className="mr-2" />}
					{t('integrations.sheet.connectManual')}
				</Button>
			</SheetFooter>
		</div>
	)
}

