}

export function ShopifyOAuthForm({ type, onConnected, className, ...props }: ShopifyOAuthFormProps) {
	const { t } = useTranslation()
	const oauth = useOauth()

	return (
		<SheetFooter className={className} {...props}>
			<Button
				type="button"
				className="w-full"
				disabled={oauth.isPending}
				onClick={() => oauth.start({ type: 'SALES_CHANNEL', platform: 'SHOPIFY' })}
			>
				{oauth.isPending && <Spinner className="mr-2" />}
				{t('integrations.sheet.connectOauth')}
			</Button>
		</SheetFooter>
	)
}

